#include <iostream>
#include <memory>
#include <vector>

struct TreeNode {
    int data;
    std::unique_ptr<TreeNode> left;
    std::unique_ptr<TreeNode> right;

    explicit TreeNode(int val) : data(val), left(nullptr), right(nullptr) {}
};

// Recursive insertion with duplicate elimination
void insertNode(std::unique_ptr<TreeNode>& root, int val) {
    if (!root) {
        root = std::make_unique<TreeNode>(val);
    } else if (val < root->data) {
        insertNode(root->left, val);
    } else if (val > root->data) {
        insertNode(root->right, val);
    }
    // If val == root->data, duplicate is discarded
}

void inOrder(const TreeNode* root) {
    if (!root) return;
    inOrder(root->left.get());
    std::cout << root->data << " ";
    inOrder(root->right.get());
}

void preOrder(const TreeNode* root) {
    if (!root) return;
    std::cout << root->data << " ";
    preOrder(root->left.get());
    preOrder(root->right.get());
}

void postOrder(const TreeNode* root) {
    if (!root) return;
    postOrder(root->left.get());
    postOrder(root->right.get());
    std::cout << root->data << " ";
}

int main() {
    std::unique_ptr<TreeNode> root = nullptr;
    // Values from Fig. 12.21: 27 13 42 6 17 33 48 with duplicates
    std::vector<int> values = {27, 13, 42, 6, 17, 33, 48, 13, 27};
    for (int v : values) {
        insertNode(root, v);
    }

    std::cout << "PreOrder: ";
    preOrder(root.get());
    std::cout << "\nInOrder:  ";
    inOrder(root.get());
    std::cout << "\nPostOrder: ";
    postOrder(root.get());
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <cstdlib>
#include <memory>

// Legacy C-style struct according to CERT guidelines
struct LegacyNode {
    int data;
    struct LegacyNode* next;
};

void demonstrateLegacyCertPattern() {
    // ERR33-C: Always verify dynamic allocation success
    auto* node = static_cast<LegacyNode*>(std::malloc(sizeof(LegacyNode)));
    if (node == nullptr) {
        std::cerr << "Allocation failed\n";
        return;
    }
    node->data = 100;
    node->next = nullptr;

    // MEM01-C / MEM30-C: Free and immediately set to nullptr
    std::free(node);
    node = nullptr;

    // Freeing nullptr is safe and has no effect (prevents double-free crash)
    std::free(node);
    std::cout << "Legacy CERT pattern executed safely.\n";
}

// Modern C++17 RAII pattern
struct ModernNode {
    int data;
    std::unique_ptr<ModernNode> next;
    explicit ModernNode(int val) : data(val), next(nullptr) {}
};

void demonstrateModernRAII() {
    // make_unique handles allocation, throws std::bad_alloc on failure
    auto head = std::make_unique<ModernNode>(200);
    head->next = std::make_unique<ModernNode>(300);

    std::cout << "Modern RAII nodes: " << head->data 
              << " -> " << head->next->data << "\n";
    // Memory is automatically and deterministically cleaned up when head goes out of scope
}

int main() {
    demonstrateLegacyCertPattern();
    demonstrateModernRAII();
    return 0;
}
